#' 
#' T. Park, and G. Casella (2008), The Bayesian Lasso. 
#' \emph{Journal of the American Statistical Association}, 103(482):681-686.
#' 
#' @author Santiago Marin
#'
#' @encoding UTF-8
#'
bnplasso_lm <- function(X, y, intercept = TRUE, shrinkage_prior = NULL, a = NULL, b = NULL, alpha = NULL, variance_prior_type = NULL, max_iters = 10000L, burn_in = 2000L, thin = 2L, polya_urn_sampler = TRUE, verbose = TRUE) {
